"use client";

/**
 * Picker spin: a wheel picker is flicked, slows down, and lands on one row,
 * which turns the primary colour and confirms with a check.
 *
 * Written by Better Design. Painted from the theme prop, so the rows take the
 * product's ink and the chosen row takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, mix, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const SPIN_FROM = 6;
const SPIN_TO = 68;
/** Rows the flick travels before it lands. */
const TRAVEL = 15;
const CONFIRM_AT = 72;
const ROW_H = 92;
/** Degrees between two rows on the wheel. */
const STEP = 19;
const RADIUS = ROW_H / Math.sin((STEP * Math.PI) / 180);

export interface PickerSpinProps {
  /** The rows on the wheel, top to bottom. The wheel repeats them as it spins. */
  options?: string[];
  /** Index into `options` of the row the wheel lands on. */
  selected?: number;
  /** One line above the wheel. */
  caption?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const mod = (n: number, m: number) => ((n % m) + m) % m;

/** A wheel picker that flicks, slows and lands on one highlighted row. */
export function PickerSpin({
  options = ["Free", "Starter", "Plus", "Pro", "Team", "Business", "Scale"],
  selected = 3,
  caption = "Choose your plan",
  theme: themeOverride,
  font,
}: PickerSpinProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const count = Math.max(1, options.length);
  const target = mod(selected, count);

  // A quartic ease-out reads as a flick losing momentum to friction.
  const t = interpolate(frame, [SPIN_FROM, SPIN_TO], [0, 1], clamp);
  const pos = target - TRAVEL * (1 - t) ** 4;
  const confirm = spring({ frame: frame - CONFIRM_AT, fps, config: { damping: 14, stiffness: 180, mass: 0.7 } });
  const enter = easings.out(interpolate(frame, [0, 18], [0, 1], clamp));

  const first = Math.floor(pos) - 5;
  const rows = Array.from({ length: 11 }, (_, k) => first + k);

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 44, opacity: enter, transform: `translateY(${(1 - enter) * 24}px)` }}>
        <div style={{ fontSize: 56, fontWeight: 700, letterSpacing: "-0.03em", color: theme.foreground }}>{caption}</div>
        <div
          style={{
            position: "relative",
            width: 760,
            height: 560,
            borderRadius: theme.radius * 3,
            background: theme.card,
            border: `1px solid ${theme.border}`,
            boxShadow: "0 40px 80px -48px oklch(0 0 0 / 0.4)",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 28,
              right: 28,
              top: 280 - ROW_H / 2,
              height: ROW_H,
              borderRadius: theme.radius * 1.6,
              background: mix(theme.muted, mix(theme.card, theme.primary, 0.14), confirm),
              border: `1.5px solid ${withAlpha(theme.primary, 0.55 * confirm)}`,
            }}
          />
          <div style={{ position: "absolute", inset: 0, maskImage: "linear-gradient(transparent, oklch(0 0 0) 32%, oklch(0 0 0) 68%, transparent)" }}>
            {rows.map((r) => {
              const angle = (r - pos) * STEP;
              if (Math.abs(angle) > 86) return null;
              const rad = (angle * Math.PI) / 180;
              const isPick = r === Math.round(pos) && mod(r, count) === target;
              const color = isPick ? mix(theme.foreground, theme.primary, confirm) : theme.foreground;
              return (
                <div
                  key={r}
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    top: 280 - ROW_H / 2,
                    height: ROW_H,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 50,
                    fontWeight: isPick ? 600 : 500,
                    letterSpacing: "-0.02em",
                    color,
                    opacity: 0.25 + 0.75 * Math.cos(rad) ** 3,
                    transform: `translateY(${RADIUS * Math.sin(rad)}px) scaleY(${Math.cos(rad)})`,
                  }}
                >
                  {options[mod(r, count)]}
                </div>
              );
            })}
          </div>
          <div
            style={{
              position: "absolute",
              right: 56,
              top: 280 - 24,
              width: 48,
              height: 48,
              borderRadius: 24,
              background: theme.primary,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: Math.min(1, confirm * 1.5),
              transform: `scale(${confirm})`,
            }}
          >
            <svg width="26" height="26" viewBox="0 0 24 24" fill="none">
              <path d="M5 12.5l4.5 4.5L19 7.5" stroke={theme.primaryForeground} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
